(function() {
    document.querySelectorAll('.nav-item.has-mega').forEach(function(item) {
      var panel = item.querySelector('.mega-panel');
      var timer;
      function openMenu()  { clearTimeout(timer); item.classList.add('mega-open'); }
      function closeMenu() { timer = setTimeout(function() { item.classList.remove('mega-open'); }, 120); }
      item.addEventListener('mouseenter', openMenu);
      item.addEventListener('mouseleave', closeMenu);
      if (panel) {
        panel.addEventListener('mouseenter', openMenu);
        panel.addEventListener('mouseleave', closeMenu);
      }
    });
  })();

function toggleFaq(el) {
    var item = el.parentElement;
    var icon = el.querySelector('.faq-icon');
    var isOpen = item.classList.contains('open');
    document.querySelectorAll('.faq-item').forEach(function(i) {
      i.classList.remove('open');
      i.querySelector('.faq-icon').textContent = '+';
    });
    if (!isOpen) { item.classList.add('open'); icon.textContent = '−'; }
  }

(function() {
  var steps = document.querySelector('.workflow-steps');
  if (!steps || window.innerWidth > 768) return;
  function isInView() {
    var r = steps.getBoundingClientRect();
    return r.top <= window.innerHeight * 0.6 && r.bottom >= window.innerHeight * 0.2;
  }
  function atEnd() { return steps.scrollLeft + steps.clientWidth >= steps.scrollWidth - 10; }
  function atStart() { return steps.scrollLeft <= 5; }
  window.addEventListener('wheel', function(e) {
    if (!isInView()) return;
    if (atEnd() && e.deltaY > 0) return;
    if (atStart() && e.deltaY < 0) return;
    e.preventDefault();
    steps.scrollBy({ left: e.deltaY * 1.5, behavior: "smooth" });
  }, { passive: false });
  var tStartX = 0, tStartY = 0, tScrollLeft = 0;
  document.addEventListener('touchstart', function(e) {
    tStartX = e.touches[0].clientX;
    tStartY = e.touches[0].clientY;
    tScrollLeft = steps.scrollLeft;
  }, { passive: true });
  document.addEventListener('touchmove', function(e) {
    if (!isInView()) return;
    var dx = tStartX - e.touches[0].clientX;
    var dy = tStartY - e.touches[0].clientY;
    if (Math.abs(dx) >= Math.abs(dy)) return;
    if (atEnd() && dy > 0) return;
    if (atStart() && dy < 0) return;
    e.preventDefault();
    steps.scrollLeft = tScrollLeft + dy * 1.2;
  }, { passive: false });
})()
